#include <stdio.h>
#include <stdlib.h>

#define MAXC 1005

int A[2][MAXC];
int height[MAXC];
int stack[MAXC];
int left_bound[MAXC];

int main() {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    int cur = 0, prev = 1;
    for (int j = 0; j < C; j++) {
        scanf("%d", &A[cur][j]);
    }

    int max_area = 0;

    for (int i = 1; i < L; i++) {
        // Swap cur and prev
        cur ^= 1;
        prev ^= 1;

        for (int j = 0; j < C; j++) {
            scanf("%d", &A[cur][j]);
        }

        // Compute B for row i-1
        // B has C-1 columns: j from 0 to C-2
        for (int j = 0; j < C - 1; j++) {
            // Check condition: A[prev][j] + A[cur][j+1] <= A[prev][j+1] + A[cur][j]
            if (A[prev][j] + A[cur][j + 1] <= A[prev][j + 1] + A[cur][j]) {
                height[j]++;
            } else {
                height[j] = 0;
            }
        }

        // Largest rectangle in histogram of size C - 1
        int top = 0;
        int m = C - 1;

        for (int j = 0; j < m; j++) {
            while (top > 0 && height[stack[top - 1]] >= height[j]) {
                top--;
            }
            left_bound[j] = (top == 0) ? -1 : stack[top - 1];
            stack[top++] = j;
        }

        top = 0;
        for (int j = m - 1; j >= 0; j--) {
            while (top > 0 && height[stack[top - 1]] >= height[j]) {
                top--;
            }
            int right_bound = (top == 0) ? m : stack[top - 1];
            stack[top++] = j;

            int h = height[j];
            if (h > 0) {
                int w = right_bound - left_bound[j] - 1;
                int area = (h + 1) * (w + 1);
                if (area > max_area) {
                    max_area = area;
                }
            }
        }
    }

    printf("%d\n", max_area);

    return 0;
}
